import numpy as np
import pandas as pd

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    T = 1.0
    try:
        T = float(regime.config['T'])
    except Exception:
        T = 1.0
    mu = 91.86349721 + 0.60815864*T - 1.16978618*(T**2)
    sigma = 1.9828271348169342
    y = np.clip(rng.normal(mu, sigma, size=int(n)), 0.0, 100.0)
    return pd.DataFrame({'unit_id': np.arange(int(n), dtype=int), 'y': y})

